    "Die Pause muss kürzer sein als die Arbeitszeit.": "The break must be shorter than the working time.",
    "Die Person bekommt wieder Zugang (und belegt einen Platz).": "The person gets access again (and takes a seat).",
    "Die Person installiert Zunft, registriert sich mit der eigenen E-Mail und scannt diesen Code (oder tippt ihn ein).": "The person installs Zunft, registers with their own e-mail and scans this code (or types it in).",
    "Die Person kommt sofort nicht mehr in den Betrieb. Ihre Notizen bleiben erhalten. Der Platz wird frei.": "The person is immediately removed from the business. Their notes are kept. The seat becomes free.",
    "Die Person verliert sofort jede Verbindung zu deinem Betrieb: keine Aufträge, keine Kunden, keine Daten. Ihre bisherigen Notizen bleiben bei den Aufträgen (mit ihrem Namen). Ihr Konto gehört ihr: sie kann damit einen eigenen Betrieb gründen oder einem anderen beitreten. Der Platz wird frei.": "The person immediately loses every connection to your business: no jobs, no customers, no data. Their previous notes stay with the jobs (with their name). The account belongs to them: they can start their own business or join another. The seat becomes free.",
    "Die Rechnung hat keine Positionen.": "The invoice has no items.",
