    "Erstellt": "Issued",
    "Es wird eine Stornorechnung mit eigener Nummer erstellt, die diese Rechnung aufhebt. Die Rechnung selbst bleibt unverändert gespeichert und wird als „Storniert“ markiert.\n\nDie Notizen des Auftrags werden wieder frei. Danach kannst du den Auftrag erneut prüfen, korrigieren und eine neue Rechnung erstellen.\n\nDas kann nicht rückgängig gemacht werden.": "A credit note with its own number is created that cancels this invoice. The invoice itself stays saved unchanged and is marked \"Canceled\".\n\nThe notes of the job become free again. Afterwards you can check the job again, correct it and create a new invoice.\n\nThis cannot be undone.",
