    "Das ist kein Einladungscode von Zunft.": "Bu, Zunft'a ait bir davet kodu değil.",
    "Das legt einen NEUEN Betrieb an, dem du als Inhaber gehörst. Wurdest du von deinem Chef eingeladen? Dann geh zurück und wähle „Ich wurde eingeladen“.": "Bu, sahibi olduğun YENİ bir işletme oluşturur. Patronun seni davet ettiyse geri dön ve \"Davet edildim\"i seç.",
    "Das war nicht möglich (nicht mehr zugewiesen?).": "Bu mümkün olmadı (artık atanmamış olabilir mi?).",
    "Datum": "Tarih",
    "Davon": "Bunun içinde",
    "Dein Chef zeigt dir in der App unter „Betrieb → Team“ einen QR-Code und einen Code mit 8 Zeichen. Scanne den QR-Code oder tippe den Code ein.": "Patronun sana uygulamada \"İşletme → Ekip\" altında bir QR kodu ve 8 karakterlik bir kod gösterir. QR kodu tara veya kodu yaz.",
    "Dein Konto und dein Zugang werden gelöscht. Das kann nicht rückgängig gemacht werden. Notizen, die du für einen Betrieb aufgenommen hast, bleiben dort beim Auftrag (nur dein Name als Text).": "Hesabın ve erişimin silinecek. Bu geri alınamaz. Bir işletme için kaydettiğin notlar orada işte kalır (yalnızca adın metin olarak).",
