    "Der Export ist fehlgeschlagen. Bitte Internetverbindung prüfen und erneut versuchen.": "Dışa aktarma başarısız oldu. Lütfen internet bağlantısını kontrol edip tekrar dene.",
    "Der Kunde existiert nicht mehr": "Müşteri artık yok",
