    "Der Server hat die Anfrage abgelehnt. Bitte später erneut versuchen.": "Sunucu isteği reddetti. Lütfen daha sonra tekrar dene.",
    "Der Server ist gerade nicht erreichbar.": "Sunucuya şu anda ulaşılamıyor.",
    "Der Speicher deines Pakets ist voll. Für neue Aufnahmen und Belege wird ein größeres Paket gebraucht.": "Paketinin depolama alanı dolu. Yeni kayıtlar ve fişler için daha büyük bir paket gerekir.",
    "Der Speicher ist fast voll. Für mehr Speicher wird ein größeres Paket gebraucht.": "Depolama alanı neredeyse dolu. Daha fazla alan için daha büyük bir paket gerekir.",
    "Der Speicher ist voll: neue Aufnahmen und Belege werden abgelehnt. Für mehr Speicher wird ein größeres Paket gebraucht. Rechnungen können weiter erstellt werden.": "Depolama alanı dolu: yeni kayıtlar ve fişler reddedilir. Daha fazla alan için daha büyük bir paket gerekir. Faturalar oluşturulmaya devam edebilir.",
