    "Die Datei wurde abgelehnt.": "Dosya reddedildi.",
    "Die Erlaubnis für Benachrichtigungen fehlt. Bitte in den Handy-Einstellungen für Zunft erlauben.": "Bildirim izni eksik. Lütfen telefon ayarlarından Zunft için izin ver.",
    "Die Kamera ist nicht verfügbar. Bitte den Zugriff in den Einstellungen erlauben oder den Code von Hand eintippen.": "Kamera kullanılamıyor. Lütfen ayarlardan erişime izin ver veya kodu elle yaz.",
    "Die Karte konnte nicht geöffnet werden.": "Harita açılamadı.",
