    "Die Person kommt sofort nicht mehr in den Betrieb. Ihre Notizen bleiben erhalten. Der Platz wird frei.": "يخرج الشخص فوراً من المنشأة. تبقى ملاحظاته. يصبح المقعد شاغراً.",
