    "Noch keine Kunden. Lege einen Kunden an oder sprich eine Notiz ein – neue Kunden werden automatisch erkannt.": "لا يوجد عملاء بعد. أنشئ عميلاً أو سجّل ملاحظة – يتم التعرف على العملاء الجدد تلقائياً.",
    "Noch keine Notizen. Nimm eine Notiz auf (oder tippe sie ein): Arbeitszeit, Material, Besonderheiten. Du kannst beliebig viele Notizen machen, auch an mehreren Tagen.": "لا توجد ملاحظات بعد. سجّل ملاحظة (أو اكتبها): وقت العمل، المواد، أمور خاصة. يمكنك تسجيل أي عدد من الملاحظات، وعلى عدة أيام أيضاً.",
