    "Das legt einen NEUEN Betrieb an, dem du als Inhaber gehörst. Wurdest du von deinem Chef eingeladen? Dann geh zurück und wähle „Ich wurde eingeladen“.": "Kjo krijon një biznes të RI që e ke ti. Të ftoi shefi yt? Atëherë kthehu mbrapa dhe zgjidh \"Më ftuan\".",
