    "Davon": "Nga to",
    "Dein Chef zeigt dir in der App unter „Betrieb → Team“ einen QR-Code und einen Code mit 8 Zeichen. Scanne den QR-Code oder tippe den Code ein.": "Shefi yt të tregon në aplikacion te \"Biznesi → Ekipi\" një kod QR dhe një kod me 8 karaktere. Skano kodin QR ose shkruaj kodin.",
