    "Erledigt ({0})": "Kryer ({0})",
    "Erstellt": "Lëshuar",
    "Es wird eine Stornorechnung mit eigener Nummer erstellt, die diese Rechnung aufhebt. Die Rechnung selbst bleibt unverändert gespeichert und wird als „Storniert“ markiert.\n\nDie Notizen des Auftrags werden wieder frei. Danach kannst du den Auftrag erneut prüfen, korrigieren und eine neue Rechnung erstellen.\n\nDas kann nicht rückgängig gemacht werden.": "Krijohet një faturë anulimi me numër të vet që e anulon këtë faturë. Vetë fatura mbetet e ruajtur e pandryshuar dhe shënohet \"Anuluar\".\n\nShënimet e punës lirohen përsëri. Pastaj mund ta kontrollosh punën, ta korrigjosh dhe të krijosh një faturë të re.\n\nKjo nuk kthehet mbrapsht.",
    "Es wurde nichts aufgenommen.": "Nuk u regjistrua asgjë.",
    "Fast geschafft: Wir haben dir eine E-Mail geschickt. Bitte bestätige die Adresse und melde dich dann an.": "Pothuajse gati: të dërguam një e-mail. Konfirmo adresën dhe pastaj hyr.",
