    "Für die E-Rechnung braucht der Kunde eine vollständige Anschrift (Straße, PLZ, Ort).": "Për faturën elektronike klienti ka nevojë për adresë të plotë (rruga, kodi postar, qyteti).",
    "Für die E-Rechnung fehlt die IBAN des Betriebs (Betrieb → Bearbeiten).": "Për faturën elektronike mungon IBAN-i i biznesit (Biznesi → Ndrysho).",
    "Für die E-Rechnung fehlt die Steuernummer oder USt-IdNr. des Betriebs.": "Për faturën elektronike mungon numri tatimor ose ID-ja e TVSH-së e biznesit.",
    "Für die E-Rechnung fehlt die vollständige Anschrift des Betriebs.": "Për faturën elektronike mungon adresa e plotë e biznesit.",
    "Für diesen Auftrag ist Zeit erfasst: {0} Std ({1}).": "Për këtë punë është regjistruar kohë: {0} orë ({1}).",
