    "Keine Verbindung. Zum Fertigstellen wird Internet gebraucht, weil die Nummer vom Server vergeben wird. Deine Änderungen bleiben erhalten - bitte später noch einmal versuchen.": "Pa lidhje. Përfundimi kërkon internet sepse numrin e jep serveri. Ndryshimet e tua ruhen - provo përsëri më vonë.",
