    "Leer = Einkaufspreis unverändert weitergeben. Mit 10 wird jedes Material aus einem Beleg um 10 % teurer in die Rechnung übernommen. Im Prüfbildschirm kann jeder Preis noch geändert werden.": "Bosh = kalo çmimin e blerjes të pandryshuar. Me 10 çdo material nga një faturë blerjeje bëhet 10 % më i shtrenjtë në faturë. Çdo çmim mund të ndryshohet ende në ekranin e kontrollit.",
