    "Meister und Gesellen können eigene Kunden und Aufträge erstellen. Inhaber und Büro dürfen das immer.": "Mjeshtrit dhe punëtorët mund të krijojnë klientë dhe punë të veta. Pronari dhe zyra gjithmonë mund.",
    "Mindestens eine Position ist ungültig (Menge, Preis oder Bezeichnung).": "Të paktën një pozicion është i pavlefshëm (sasia, çmimi ose përshkrimi).",
