    "Noch kein Kunde": "Ende pa klient",
    "Noch keine Aufträge. Lege mit „Neuer Auftrag“ den ersten an, dann kannst du ihm Sprachnotizen hinzufügen.": "Ende pa punë. Krijo të parën me \"Punë e re\", pastaj mund t'i shtosh shënime zanore.",
    "Noch keine Kunden. Lege einen Kunden an oder sprich eine Notiz ein – neue Kunden werden automatisch erkannt.": "Ende pa klientë. Krijo një klient ose thuaj një shënim – klientët e rinj njihen automatikisht.",
    "Noch keine Notizen. Nimm eine Notiz auf (oder tippe sie ein): Arbeitszeit, Material, Besonderheiten. Du kannst beliebig viele Notizen machen, auch an mehreren Tagen.": "Ende pa shënime. Regjistro një shënim (ose shkruaje): koha e punës, materiali, veçoritë. Mund të bësh sa shënime të duash, edhe në disa ditë.",
    "Noch keine erledigten Aufträge. Abgeschlossene und abgerechnete Aufträge erscheinen hier.": "Ende pa punë të përfunduara. Punët e mbyllura dhe të faturuara shfaqen këtu.",
