    "Die Person kommt sofort nicht mehr in den Betrieb. Ihre Notizen bleiben erhalten. Der Platz wird frei.": "Osoba natychmiast przestaje należeć do firmy. Jej notatki zostają. Miejsce się zwalnia.",
