    "Diese Notiz gehört zu keinem Auftrag. Bitte verwerfen und neu aufnehmen.": "Ta notatka nie należy do żadnego zlecenia. Odrzuć ją i nagraj ponownie.",
    "Diese Rechnung wurde schon storniert.": "Ta faktura została już anulowana.",
    "Diese Zeit wurde schon abgerechnet und kann nicht gelöscht werden.": "Ten czas został już rozliczony i nie można go usunąć.",
    "Diesen Kunden gibt es schon": "Ten klient już istnieje",
    "Dieser Auftrag ist abgerechnet. Es können keine Notizen mehr aufgenommen werden.": "To zlecenie jest rozliczone. Nie można już nagrywać notatek.",
    "Dieser Auftrag ist abgeschlossen. Es können keine Notizen mehr aufgenommen werden.": "To zlecenie jest zamknięte. Nie można już nagrywać notatek.",
    "Dieser Kunde existiert nicht mehr.": "Ten klient już nie istnieje.",
    "Dieser Kunde hat Angebote oder Rechnungen und kann nicht gelöscht werden (gesetzliche Aufbewahrung).": "Ten klient ma oferty lub faktury i nie można go usunąć (obowiązkowe przechowywanie).",
    "Dieses Handy hat keine Adresse für Meldungen bekommen. Bitte später noch einmal versuchen.": "Ten telefon nie otrzymał adresu dla powiadomień. Spróbuj ponownie później.",
    "Dieses PDF wird gelesen und als Beleg gespeichert.": "Ten plik PDF zostanie odczytany i zapisany jako paragon.",
    "Dir ist noch kein Auftrag zugewiesen. Sobald der Inhaber oder das Büro dir einen Auftrag zuweist, erscheint er hier.": "Nie przypisano Ci jeszcze żadnego zlecenia. Gdy właściciel lub biuro przypisze Ci zlecenie, pojawi się tutaj.",
    "Donnerstag": "Czwartek",
    "Du verlierst den Zugang zu allen Aufträgen und Kunden dieses Betriebs. Deine Notizen bleiben dort erhalten. Dein Konto bleibt bestehen: du kannst einen eigenen Betrieb gründen oder einem anderen beitreten.": "Tracisz dostęp do wszystkich zleceń i klientów tej firmy. Twoje notatki tam zostają. Twoje konto zostaje: możesz założyć własną firmę lub dołączyć do innej.",
    "E-Mail (Betrieb)": "E-mail (firma)",
    "E-Mail oder Passwort ist falsch.": "E-mail lub hasło jest nieprawidłowe.",
    "E-Rechnung": "E-faktura",
    "EUR": "EUR",
    "Ein Angebot ist keine Rechnung.": "Oferta nie jest fakturą.",
    "Ein Betrieb kann nicht mit einem Tipp gelöscht werden: Rechnungen müssen gesetzlich über Jahre aufbewahrt werden (GoBD). Wenn du deinen Betrieb schließen oder dein Konto löschen möchtest, wende dich bitte an den Support. Mitarbeiter kannst du unter „Team“ entfernen.": "Firmy nie można usunąć jednym dotknięciem: faktury muszą być z mocy prawa przechowywane przez lata (GoBD). Jeśli chcesz zamknąć firmę lub usunąć konto, skontaktuj się z pomocą. Pracowników możesz usunąć w „Zespół”.",
    "Ein Eintrag darf höchstens 24 Stunden dauern.": "Wpis może trwać najwyżej 24 godziny.",
    "Ein Termin darf höchstens 31 Tage dauern.": "Termin może trwać najwyżej 31 dni.",
