    "Dein Chef zeigt dir in der App unter „Betrieb → Team“ einen QR-Code und einen Code mit 8 Zeichen. Scanne den QR-Code oder tippe den Code ein.": "Șeful tău îți arată în aplicație la „Firmă → Echipă” un cod QR și un cod de 8 caractere. Scanează codul QR sau scrie codul.",
    "Dein Konto und dein Zugang werden gelöscht. Das kann nicht rückgängig gemacht werden. Notizen, die du für einen Betrieb aufgenommen hast, bleiben dort beim Auftrag (nur dein Name als Text).": "Contul și accesul tău vor fi șterse. Acest lucru nu poate fi anulat. Notele pe care le-ai înregistrat pentru o firmă rămân acolo la lucrare (doar numele tău ca text).",
