    "Die Erlaubnis für Benachrichtigungen fehlt. Bitte in den Handy-Einstellungen für Zunft erlauben.": "Lipsește permisiunea pentru notificări. Permite-o pentru Zunft în setările telefonului.",
    "Die Kamera ist nicht verfügbar. Bitte den Zugriff in den Einstellungen erlauben oder den Code von Hand eintippen.": "Camera nu este disponibilă. Permite accesul în setări sau scrie codul manual.",
