    "Die Notizen konnten nicht geladen werden. Bitte Internetverbindung prüfen.": "Notele nu au putut fi încărcate. Verifică conexiunea la internet.",
    "Die Pause muss kürzer sein als die Arbeitszeit.": "Pauza trebuie să fie mai scurtă decât timpul de lucru.",
    "Die Person bekommt wieder Zugang (und belegt einen Platz).": "Persoana primește din nou acces (și ocupă un loc).",
    "Die Person installiert Zunft, registriert sich mit der eigenen E-Mail und scannt diesen Code (oder tippt ihn ein).": "Persoana instalează Zunft, se înregistrează cu propriul e-mail și scanează acest cod (sau îl scrie).",
    "Die Person kommt sofort nicht mehr in den Betrieb. Ihre Notizen bleiben erhalten. Der Platz wird frei.": "Persoana iese imediat din firmă. Notele ei rămân. Locul se eliberează.",
    "Die Person verliert sofort jede Verbindung zu deinem Betrieb: keine Aufträge, keine Kunden, keine Daten. Ihre bisherigen Notizen bleiben bei den Aufträgen (mit ihrem Namen). Ihr Konto gehört ihr: sie kann damit einen eigenen Betrieb gründen oder einem anderen beitreten. Der Platz wird frei.": "Persoana pierde imediat orice legătură cu firma ta: fără lucrări, fără clienți, fără date. Notele ei de până acum rămân la lucrări (cu numele ei). Contul îi aparține: își poate fonda propria firmă sau se poate alătura alteia. Locul se eliberează.",
    "Die Rechnung hat keine Positionen.": "Factura nu are poziții.",
    "Die Rechnung ist schon als bezahlt markiert. Bitte zuerst mit dem Steuerberater klären, wie sie zu korrigieren ist.": "Factura este deja marcată ca plătită. Clarifică mai întâi cu consultantul fiscal cum se corectează.",
    "Die Rechnung konnte nicht storniert werden.": "Factura nu a putut fi anulată.",
    "Die Verarbeitung ist fehlgeschlagen.": "Procesarea a eșuat.",
    "Dienstag": "Marți",
    "Diese Notiz gehört zu keinem Auftrag. Bitte verwerfen und neu aufnehmen.": "Această notă nu aparține nicio lucrare. Renunță la ea și înregistreaz-o din nou.",
    "Diese Rechnung wurde schon storniert.": "Această factură a fost deja anulată.",
    "Diese Zeit wurde schon abgerechnet und kann nicht gelöscht werden.": "Acest timp a fost deja facturat și nu poate fi șters.",
    "Diesen Kunden gibt es schon": "Acest client există deja",
    "Dieser Auftrag ist abgerechnet. Es können keine Notizen mehr aufgenommen werden.": "Această lucrare este facturată. Nu se mai pot înregistra note.",
    "Dieser Auftrag ist abgeschlossen. Es können keine Notizen mehr aufgenommen werden.": "Această lucrare este închisă. Nu se mai pot înregistra note.",
    "Dieser Kunde existiert nicht mehr.": "Acest client nu mai există.",
    "Dieser Kunde hat Angebote oder Rechnungen und kann nicht gelöscht werden (gesetzliche Aufbewahrung).": "Acest client are oferte sau facturi și nu poate fi șters (păstrare legală).",
    "Dieses Handy hat keine Adresse für Meldungen bekommen. Bitte später noch einmal versuchen.": "Acest telefon nu a primit o adresă pentru notificări. Încearcă din nou mai târziu.",
    "Dieses PDF wird gelesen und als Beleg gespeichert.": "Acest PDF este citit și salvat ca bon.",
    "Dir ist noch kein Auftrag zugewiesen. Sobald der Inhaber oder das Büro dir einen Auftrag zuweist, erscheint er hier.": "Încă nu ți-a fost atribuită nicio lucrare. De îndată ce proprietarul sau biroul îți atribuie una, apare aici.",
    "Donnerstag": "Joi",
    "Du verlierst den Zugang zu allen Aufträgen und Kunden dieses Betriebs. Deine Notizen bleiben dort erhalten. Dein Konto bleibt bestehen: du kannst einen eigenen Betrieb gründen oder einem anderen beitreten.": "Pierzi accesul la toate lucrările și clienții acestei firme. Notele tale rămân acolo. Contul tău rămâne: îți poți fonda propria firmă sau te poți alătura alteia.",
    "E-Mail (Betrieb)": "E-mail (firmă)",
    "E-Mail oder Passwort ist falsch.": "E-mailul sau parola este greșită.",
    "E-Rechnung": "Factură electronică",
    "EUR": "EUR",
    "Ein Angebot ist keine Rechnung.": "O ofertă nu este o factură.",
    "Ein Betrieb kann nicht mit einem Tipp gelöscht werden: Rechnungen müssen gesetzlich über Jahre aufbewahrt werden (GoBD). Wenn du deinen Betrieb schließen oder dein Konto löschen möchtest, wende dich bitte an den Support. Mitarbeiter kannst du unter „Team“ entfernen.": "O firmă nu poate fi ștearsă cu o atingere: facturile trebuie păstrate prin lege ani de zile (GoBD). Dacă vrei să închizi firma sau să ștergi contul, contactează suportul. Angajații îi poți elimina la „Echipă”.",
    "Ein Eintrag darf höchstens 24 Stunden dauern.": "O înregistrare poate dura cel mult 24 de ore.",
    "Ein Termin darf höchstens 31 Tage dauern.": "O programare poate dura cel mult 31 de zile.",
    "Eine Position hat eine ungültige Menge.": "O poziție are o cantitate invalidă.",
    "Eine Position hat keine Bezeichnung.": "O poziție nu are denumire.",
    "Einer der Kunden wurde schon zusammengeführt.": "Unul dintre clienți a fost deja îmbinat.",
    "Einige Änderungen wurden abgelehnt": "Unele modificări au fost respinse",
    "Einladung zurückziehen?": "Retragi invitația?",
    "Einladung: {0}": "Invitație: {0}",
    "Einmal benutzbar, gültig bis {0}": "Utilizabil o singură dată, valabil până la {0}",
