    "Erledigt": "Gata",
    "Erledigt ({0})": "Gata ({0})",
    "Erstellt": "Emis",
    "Es wird eine Stornorechnung mit eigener Nummer erstellt, die diese Rechnung aufhebt. Die Rechnung selbst bleibt unverändert gespeichert und wird als „Storniert“ markiert.\n\nDie Notizen des Auftrags werden wieder frei. Danach kannst du den Auftrag erneut prüfen, korrigieren und eine neue Rechnung erstellen.\n\nDas kann nicht rückgängig gemacht werden.": "Se creează o factură de stornare cu număr propriu, care anulează această factură. Factura în sine rămâne salvată neschimbată și este marcată „Anulat”.\n\nNotele lucrării devin din nou libere. Apoi poți verifica din nou lucrarea, o poți corecta și poți crea o factură nouă.\n\nAcest lucru nu poate fi anulat.",
    "Es wurde nichts aufgenommen.": "Nu s-a înregistrat nimic.",
    "Fast geschafft: Wir haben dir eine E-Mail geschickt. Bitte bestätige die Adresse und melde dich dann an.": "Aproape gata: ți-am trimis un e-mail. Confirmă adresa și apoi autentifică-te.",
    "Februar": "Februarie",
    "Firma": "Firmă",
    "Format: DE und 9 Ziffern": "Format: DE și 9 cifre",
