    "Alle Aufträge wandern zum bleibenden Kunden. Fehlende Angaben werden ergänzt, abweichende Angaben stehen danach in den Notizen. Bereits erstellte Angebote und Rechnungen bleiben unverändert (sie müssen laut Gesetz so aufbewahrt werden).": "Все заказы переходят к клиенту, который остаётся. Недостающие данные дополняются, отличающиеся данные затем попадают в заметки. Уже выставленные предложения и счета остаются без изменений (по закону они должны храниться в таком виде).",
