    "Auf diesem Handy ist keine Bildschirmsperre (PIN, Muster, Fingerabdruck oder Gesicht) eingerichtet. Bitte zuerst in den Handy-Einstellungen einrichten.": "На этом телефоне не настроена блокировка экрана (PIN, графический ключ, отпечаток или лицо). Сначала настройте её в настройках телефона.",
