    "Bitte mindestens eine Position hinzufügen.": "Пожалуйста, добавьте хотя бы одну позицию.",
    "Bitte mit Fingerabdruck, Gesicht oder PIN entsperren.": "Пожалуйста, разблокируйте отпечатком пальца, лицом или PIN-кодом.",
    "Bitte zuerst Steuernummer oder USt-IdNr. unter „Betrieb“ eintragen.": "Пожалуйста, сначала введите налоговый номер или номер плательщика НДС в разделе «Предприятие».",
    "Bitte zuerst die Anschrift deines Betriebs unter „Betrieb“ eintragen.": "Пожалуйста, сначала введите адрес вашего предприятия в разделе «Предприятие».",
