    "Das hat nicht geklappt. Bitte erneut versuchen.": "Не получилось. Попробуйте ещё раз.",
    "Das ist derselbe Kunde.": "Это тот же клиент.",
    "Das ist für den Inhaber eines Betriebs nicht möglich.": "Это невозможно для владельца предприятия.",
    "Das ist kein Einladungscode von Zunft.": "Это не код приглашения Zunft.",
    "Das legt einen NEUEN Betrieb an, dem du als Inhaber gehörst. Wurdest du von deinem Chef eingeladen? Dann geh zurück und wähle „Ich wurde eingeladen“.": "Это создаёт НОВОЕ предприятие, которым вы владеете. Вас пригласил начальник? Тогда вернитесь и выберите «Меня пригласили».",
    "Das war nicht möglich (nicht mehr zugewiesen?).": "Это было невозможно (больше не назначено?).",
    "Datum": "Дата",
    "Davon": "Из них",
    "Dein Chef zeigt dir in der App unter „Betrieb → Team“ einen QR-Code und einen Code mit 8 Zeichen. Scanne den QR-Code oder tippe den Code ein.": "Ваш начальник показывает вам в приложении в разделе «Предприятие → Команда» QR-код и код из 8 символов. Отсканируйте QR-код или введите код.",
    "Dein Konto und dein Zugang werden gelöscht. Das kann nicht rückgängig gemacht werden. Notizen, die du für einen Betrieb aufgenommen hast, bleiben dort beim Auftrag (nur dein Name als Text).": "Ваш аккаунт и доступ будут удалены. Это нельзя отменить. Заметки, которые вы записали для предприятия, остаются там у заказа (только ваше имя как текст).",
    "Deine erfasste Arbeitszeit": "Ваше записанное рабочее время",
    "Der Anruf konnte nicht gestartet werden.": "Не удалось начать звонок.",
