    "Der Auftrag existiert nicht mehr": "Заказа больше нет",
    "Der Beleg konnte nicht gespeichert werden.": "Не удалось сохранить чек.",
    "Der Code besteht aus 8 Zeichen (Buchstaben und Ziffern).": "Код состоит из 8 символов (буквы и цифры).",
    "Der Code ist ungültig, abgelaufen oder schon benutzt. Bitte beim Chef einen neuen Code holen.": "Код недействителен, истёк или уже использован. Получите у начальника новый код.",
    "Der Code {0} funktioniert danach nicht mehr.": "Код {0} после этого перестанет работать.",
    "Der Export ist fehlgeschlagen. Bitte Internetverbindung prüfen und erneut versuchen.": "Экспорт не удался. Проверьте подключение к интернету и попробуйте снова.",
    "Der Kunde existiert nicht mehr": "Клиента больше нет",
    "Der Kunde existiert nicht mehr.": "Клиента больше нет.",
    "Der Server hat die Anfrage abgelehnt. Bitte später erneut versuchen.": "Сервер отклонил запрос. Попробуйте позже.",
    "Der Server ist gerade nicht erreichbar.": "Сервер сейчас недоступен.",
    "Der Speicher deines Pakets ist voll. Für neue Aufnahmen und Belege wird ein größeres Paket gebraucht.": "Хранилище вашего тарифа заполнено. Для новых записей и чеков нужен более крупный тариф.",
    "Der Speicher ist fast voll. Für mehr Speicher wird ein größeres Paket gebraucht.": "Хранилище почти заполнено. Для большего объёма нужен более крупный тариф.",
    "Der Speicher ist voll: neue Aufnahmen und Belege werden abgelehnt. Für mehr Speicher wird ein größeres Paket gebraucht. Rechnungen können weiter erstellt werden.": "Хранилище заполнено: новые записи и чеки отклоняются. Для большего объёма нужен более крупный тариф. Счета по-прежнему можно создавать.",
    "Der Status konnte nicht geändert werden.": "Не удалось изменить статус.",
    "Der Upload wurde abgelehnt.": "Загрузка отклонена.",
    "Der laufende Timer für „{0}“ wurde beendet ({1} Std).": "Запущенный таймер для «{0}» остановлен ({1} ч).",
    "Deutsche IBAN hat 22 Zeichen": "Немецкий IBAN состоит из 22 символов",
    "Dezember": "Декабрь",
    "Die Aufnahme konnte nicht abgespielt werden.": "Не удалось воспроизвести запись.",
    "Die Aufnahme konnte nicht geladen werden. Bitte Internetverbindung prüfen.": "Не удалось загрузить запись. Проверьте подключение к интернету.",
    "Die Aufnahme konnte nicht gespeichert werden.": "Не удалось сохранить запись.",
    "Die Aufnahme konnte nicht gestartet werden.": "Не удалось начать запись.",
    "Die Aufnahme war zu kurz.": "Запись была слишком короткой.",
    "Die Belege konnten nicht geladen werden.": "Не удалось загрузить чеки.",
    "Die Bestätigung hat nicht geklappt. Die App-Sperre bleibt aus.": "Подтверждение не сработало. Блокировка приложения остаётся выключенной.",
    "Die Betriebsdaten werden noch geladen.": "Данные предприятия ещё загружаются.",
    "Die Datei ist zu groß.": "Файл слишком большой.",
    "Die Datei wurde abgelehnt.": "Файл отклонён.",
    "Die Erlaubnis für Benachrichtigungen fehlt. Bitte in den Handy-Einstellungen für Zunft erlauben.": "Нет разрешения на уведомления. Разрешите в настройках телефона для Zunft.",
    "Die Kamera ist nicht verfügbar. Bitte den Zugriff in den Einstellungen erlauben oder den Code von Hand eintippen.": "Камера недоступна. Разрешите доступ в настройках или введите код вручную.",
    "Die Karte konnte nicht geöffnet werden.": "Не удалось открыть карту.",
    "Die Notiz ist zu lang (höchstens {0} Zeichen).": "Заметка слишком длинная (не более {0} символов).",
    "Die Notiz kann nicht mehr entfernt werden (bereits abgerechnet?).": "Заметку больше нельзя удалить (уже оплачена?).",
    "Die Notiz konnte nicht gespeichert werden.": "Не удалось сохранить заметку.",
    "Die Notiz konnte nicht verarbeitet werden.": "Не удалось обработать заметку.",
    "Die Notizen konnten nicht geladen werden.": "Не удалось загрузить заметки.",
    "Die Notizen konnten nicht geladen werden. Bitte Internetverbindung prüfen.": "Не удалось загрузить заметки. Проверьте подключение к интернету.",
    "Die Pause muss kürzer sein als die Arbeitszeit.": "Перерыв должен быть короче рабочего времени.",
    "Die Person bekommt wieder Zugang (und belegt einen Platz).": "Человек снова получает доступ (и занимает место).",
    "Die Person installiert Zunft, registriert sich mit der eigenen E-Mail und scannt diesen Code (oder tippt ihn ein).": "Человек устанавливает Zunft, регистрируется со своей эл. почтой и сканирует этот код (или вводит его).",
    "Die Person kommt sofort nicht mehr in den Betrieb. Ihre Notizen bleiben erhalten. Der Platz wird frei.": "Человек сразу выходит из предприятия. Его заметки сохраняются. Место освобождается.",
    "Die Person verliert sofort jede Verbindung zu deinem Betrieb: keine Aufträge, keine Kunden, keine Daten. Ihre bisherigen Notizen bleiben bei den Aufträgen (mit ihrem Namen). Ihr Konto gehört ihr: sie kann damit einen eigenen Betrieb gründen oder einem anderen beitreten. Der Platz wird frei.": "Человек сразу теряет любую связь с вашим предприятием: никаких заказов, клиентов, данных. Его прежние заметки остаются у заказов (с его именем). Аккаунт принадлежит ему: он может создать своё предприятие или присоединиться к другому. Место освобождается.",
    "Die Rechnung hat keine Positionen.": "В счёте нет позиций.",
    "Die Rechnung ist schon als bezahlt markiert. Bitte zuerst mit dem Steuerberater klären, wie sie zu korrigieren ist.": "Счёт уже отмечен как оплаченный. Сначала уточните у налогового консультанта, как его исправить.",
    "Die Rechnung konnte nicht storniert werden.": "Не удалось сторнировать счёт.",
    "Die Verarbeitung ist fehlgeschlagen.": "Обработка не удалась.",
    "Dienstag": "Вторник",
    "Diese Notiz gehört zu keinem Auftrag. Bitte verwerfen und neu aufnehmen.": "Эта заметка не относится ни к одному заказу. Отбросьте её и запишите заново.",
    "Diese Rechnung wurde schon storniert.": "Этот счёт уже сторнирован.",
    "Diese Zeit wurde schon abgerechnet und kann nicht gelöscht werden.": "Это время уже оплачено и не может быть удалено.",
    "Diesen Kunden gibt es schon": "Такой клиент уже есть",
    "Dieser Auftrag ist abgerechnet. Es können keine Notizen mehr aufgenommen werden.": "Этот заказ оплачен. Заметки больше нельзя записывать.",
    "Dieser Auftrag ist abgeschlossen. Es können keine Notizen mehr aufgenommen werden.": "Этот заказ закрыт. Заметки больше нельзя записывать.",
    "Dieser Kunde existiert nicht mehr.": "Этого клиента больше нет.",
    "Dieser Kunde hat Angebote oder Rechnungen und kann nicht gelöscht werden (gesetzliche Aufbewahrung).": "У этого клиента есть предложения или счета, его нельзя удалить (обязательное хранение).",
    "Dieses Handy hat keine Adresse für Meldungen bekommen. Bitte später noch einmal versuchen.": "Этот телефон не получил адрес для уведомлений. Попробуйте позже.",
    "Dieses PDF wird gelesen und als Beleg gespeichert.": "Этот PDF будет прочитан и сохранён как чек.",
    "Dir ist noch kein Auftrag zugewiesen. Sobald der Inhaber oder das Büro dir einen Auftrag zuweist, erscheint er hier.": "Вам пока не назначен ни один заказ. Как только владелец или офис назначит заказ, он появится здесь.",
    "Donnerstag": "Четверг",
    "Du verlierst den Zugang zu allen Aufträgen und Kunden dieses Betriebs. Deine Notizen bleiben dort erhalten. Dein Konto bleibt bestehen: du kannst einen eigenen Betrieb gründen oder einem anderen beitreten.": "Вы потеряете доступ ко всем заказам и клиентам этого предприятия. Ваши заметки там сохранятся. Ваш аккаунт останется: вы можете создать своё предприятие или присоединиться к другому.",
    "E-Mail (Betrieb)": "Эл. почта (предприятие)",
    "E-Mail oder Passwort ist falsch.": "Неверная эл. почта или пароль.",
    "E-Rechnung": "Электронный счёт",
    "EUR": "EUR",
    "Ein Angebot ist keine Rechnung.": "Предложение - не счёт.",
    "Ein Betrieb kann nicht mit einem Tipp gelöscht werden: Rechnungen müssen gesetzlich über Jahre aufbewahrt werden (GoBD). Wenn du deinen Betrieb schließen oder dein Konto löschen möchtest, wende dich bitte an den Support. Mitarbeiter kannst du unter „Team“ entfernen.": "Предприятие нельзя удалить одним нажатием: счета по закону должны храниться годами (GoBD). Если вы хотите закрыть предприятие или удалить аккаунт, обратитесь в поддержку. Сотрудников можно удалить в разделе «Команда».",
    "Ein Eintrag darf höchstens 24 Stunden dauern.": "Запись может длиться не более 24 часов.",
    "Ein Termin darf höchstens 31 Tage dauern.": "Встреча может длиться не более 31 дня.",
    "Eine Position hat eine ungültige Menge.": "У позиции недопустимое количество.",
    "Eine Position hat keine Bezeichnung.": "У позиции нет наименования.",
    "Einer der Kunden wurde schon zusammengeführt.": "Один из клиентов уже объединён.",
    "Einige Änderungen wurden abgelehnt": "Некоторые изменения были отклонены",
    "Einladung zurückziehen?": "Отозвать приглашение?",
    "Einladung: {0}": "Приглашение: {0}",
    "Einmal benutzbar, gültig bis {0}": "Одноразовый, действует до {0}",
    "Einschalten": "Включить",
    "Ende": "Конец",
    "Entwurf": "Черновик",
    "Erfasst von": "Записал(а)",
    "Erfasste Zeit abrechnen": "Оплатить записанное время",
    "Erledigt": "Выполнено",
    "Erledigt ({0})": "Выполнено ({0})",
    "Erstellt": "Выставлен",
    "Es wird eine Stornorechnung mit eigener Nummer erstellt, die diese Rechnung aufhebt. Die Rechnung selbst bleibt unverändert gespeichert und wird als „Storniert“ markiert.\n\nDie Notizen des Auftrags werden wieder frei. Danach kannst du den Auftrag erneut prüfen, korrigieren und eine neue Rechnung erstellen.\n\nDas kann nicht rückgängig gemacht werden.": "Создаётся сторно-счёт с собственным номером, который аннулирует этот счёт. Сам счёт остаётся сохранённым без изменений и помечается «Сторнирован».\n\nЗаметки заказа снова освобождаются. После этого вы можете снова проверить заказ, исправить его и создать новый счёт.\n\nЭто нельзя отменить.",
    "Es wurde nichts aufgenommen.": "Ничего не записано.",
    "Fast geschafft: Wir haben dir eine E-Mail geschickt. Bitte bestätige die Adresse und melde dich dann an.": "Почти готово: мы отправили вам письмо. Подтвердите адрес и затем войдите.",
    "Februar": "Февраль",
    "Firma": "Фирма",
    "Format: DE und 9 Ziffern": "Формат: DE и 9 цифр",
    "Frau": "Госпожа",
    "Freitag": "Пятница",
