    "Keine Verbindung. Zum Fertigstellen wird Internet gebraucht, weil die Nummer vom Server vergeben wird. Deine Änderungen bleiben erhalten - bitte später noch einmal versuchen.": "Немає з'єднання. Для завершення потрібен інтернет, бо номер призначає сервер. Ваші зміни збережено - спробуйте пізніше.",
    "Konto erstellen": "Створити обліковий запис",
