    "Kunden": "Клієнти",
    "Leer = Einkaufspreis unverändert weitergeben. Mit 10 wird jedes Material aus einem Beleg um 10 % teurer in die Rechnung übernommen. Im Prüfbildschirm kann jeder Preis noch geändert werden.": "Порожньо = передати закупівельну ціну без змін. При 10 кожен матеріал із чека буде в рахунку на 10 % дорожчим. Кожну ціну ще можна змінити на екрані перевірки.",
