    "Meister und Gesellen können eigene Kunden und Aufträge erstellen. Inhaber und Büro dürfen das immer.": "Майстри та підмайстри можуть створювати власних клієнтів і замовлення. Власник і офіс можуть завжди.",
    "Mindestens eine Position ist ungültig (Menge, Preis oder Bezeichnung).": "Принаймні одна позиція недопустима (кількість, ціна або найменування).",
