    "Noch keine Aufträge. Lege mit „Neuer Auftrag“ den ersten an, dann kannst du ihm Sprachnotizen hinzufügen.": "Замовлень ще немає. Створіть перше через «Нове замовлення», потім зможете додавати до нього голосові нотатки.",
    "Noch keine Kunden. Lege einen Kunden an oder sprich eine Notiz ein – neue Kunden werden automatisch erkannt.": "Клієнтів ще немає. Створіть клієнта або наговоріть нотатку – нові клієнти розпізнаються автоматично.",
    "Noch keine Notizen. Nimm eine Notiz auf (oder tippe sie ein): Arbeitszeit, Material, Besonderheiten. Du kannst beliebig viele Notizen machen, auch an mehreren Tagen.": "Нотаток ще немає. Запишіть нотатку (або напишіть): робочий час, матеріал, особливості. Можна робити скільки завгодно нотаток, у тому числі в різні дні.",
    "Noch keine erledigten Aufträge. Abgeschlossene und abgerechnete Aufträge erscheinen hier.": "Завершених замовлень ще немає. Закриті й оплачені замовлення з'являться тут.",
